// Purpose: ROW-126 (REQ-010, REQ-023) — at 360 pixels on a touch screen, a tap on any highlighted
// word, at the edges included, opens a fully visible menu; tapping outside it or Escape closes it and
// changes nothing.
// Provenance: generated by tests/invariants/suggestions-population.ts from dictionary-es 4.0.0 (the
// SHA-256-pinned oracle, D-029) with a fresh seed per run; positions are the test's own record.
//
// Test argument
// ROW-126 promise: at 360 pixels on a touch screen a tap on any highlighted word, at the edges
//   included, opens a fully visible menu; tapping outside or Escape closes it and changes nothing
//   (origin: domain; REQ-010 the menu, REQ-023 "at a phone width of 360 pixels any control is
//   unreachable" fails it).
// ROW-126 wrong product: a menu positioned at the word's left edge with a fixed desktop width, which
//   runs off the right side of a 360-pixel screen for a word at the end of a line; or a menu that
//   closes only on a click (no touch), or whose closing tap lands on the text and moves or changes it.
// ROW-126 given: a touch phone at 360×780 (the phone project's own page; in Chromium a Pixel 7, in
//   WebKit an iPhone 13, at that width; Playwright's Firefox emulates no mobile device, so the other
//   projects pay the row there) and a checked offer of four lines of growing length that each start
//   and end with a fresh misspelling, so highlights stand at both edges of the box; when: each highlight is
//   tapped, and its menu closed, alternately, with Escape and with a tap outside the menu; then: each
//   tap opens a menu whose whole box lies inside the 360-pixel viewport, and after each close no menu
//   is open and the text, the highlights and the count line are as after the check.
// ROW-126 controls: the highlights reach both edges — the leftmost starts within 48 px of the box's
//   left edge and the rightmost ends in the box's right 40 % — so the edge cases are reached;
//   untouched by a menu fault.
// ROW-126 technique: every highlight tapped (no sampling of the edges), the menu measured against the
//   viewport, before/after on the text, highlights and count.
// cases: ROW-126 target=ROW-126-at-360-pixels-every-highlight-tap-opens-a-fully-visible-menu-that-closes-changing-nothing control=ROW-126-control-the-highlights-reach-both-edges-of-the-box

import { devices, expect, test, type Browser, type Page } from '@playwright/test';
import { asActor, el, enterOffer, freshRandom, openChecker, pressCheck, PRODUCT_URL, readHighlights, ROLES, type Rng } from './harness';
import { flagLocator, isTouch, openMenu, readCount, readOfferText } from './suggestions-helpers';
import { uniqueCorrectionErrors } from './suggestions-population';

const WAIT_MS = 15_000;
const VIEW = { width: 360, height: 780 };

async function phoneAt360(page: Page, browser: Browser, browserName: string): Promise<Page | null> {
  if (await isTouch(page)) {
    await page.setViewportSize(VIEW);
    return page;
  }
  if (browserName === 'chromium') return (await browser.newContext({ ...devices['Pixel 7'], viewport: VIEW, locale: 'es-ES', baseURL: PRODUCT_URL })).newPage();
  if (browserName === 'webkit') return (await browser.newContext({ ...devices['iPhone 13'], viewport: VIEW, locale: 'es-ES', baseURL: PRODUCT_URL })).newPage();
  return null;
}

function edgeOffer(rng: Rng) {
  // lines of growing length, each starting and ending with a misspelling: the short ones end well
  // inside the box, a middle one near its right edge, the longest wraps
  const w = uniqueCorrectionErrors(rng, 8).map((m) => m.wrong);
  return [`${w[0]} y ${w[1]}`, `${w[2]} para el ${w[3]}`, `${w[4]} con la persona ${w[5]}`, `${w[6]} para el equipo de trabajo ${w[7]}`].join('\n');
}

async function checkedAt360(p: Page, rng: Rng, row: string) {
  const text = edgeOffer(rng);
  await openChecker(p);
  await enterOffer(p, text);
  expect((await pressCheck(p)).status, `${row}: the check is answered`).toBe(200);
  await expect.poll(async () => (await readHighlights(p, text)).length, { message: `${row}: the eight misspellings are highlighted (seed ${rng.seed})`, timeout: WAIT_MS }).toBe(8);
  return text;
}

test('ROW-126-at-360-pixels-every-highlight-tap-opens-a-fully-visible-menu-that-closes-changing-nothing', async ({ page, browser, browserName }) => {
  asActor('anonymous');
  const p = await phoneAt360(page, browser, browserName);
  test.skip(p === null, "Playwright's Firefox emulates no mobile device; the phone, Chromium and WebKit projects pay ROW-126");
  const rng = freshRandom();
  const text = await checkedAt360(p!, rng, 'ROW-126');
  const after = { highlights: await readHighlights(p!, text), count: (await readCount(p!)).text };

  for (const [i, h] of after.highlights.entries()) {
    const flag = await flagLocator(p!, text, h.start, 'ROW-126');
    await flag.scrollIntoViewIfNeeded();
    const fb = await flag.boundingBox();
    if (!fb) throw new Error(`ROW-126: the highlight "${h.word}" has no box on screen`);
    await p!.touchscreen.tap(fb.x + fb.width / 2, fb.y + fb.height / 2);
    const menu = openMenu(p!);
    await expect(menu, `ROW-126: a tap on "${h.word}" opens its menu`).toBeVisible({ timeout: WAIT_MS });
    const mb = await menu.boundingBox();
    const vp = p!.viewportSize()!;
    expect(
      mb && mb.x >= 0 && mb.y >= 0 && mb.x + mb.width <= vp.width + 0.5 && mb.y + mb.height <= vp.height + 0.5,
      `ROW-126: the menu of "${h.word}" lies wholly inside the ${vp.width}×${vp.height} viewport — box ${JSON.stringify(mb)}`,
    ).toBe(true);

    if (i % 2 === 0) {
      await p!.keyboard.press('Escape');
    } else {
      // a tap outside the menu: on the count line when the menu leaves it free, else at the top-left corner
      const cb = await el(p!, ROLES.count).filter({ visible: true }).first().boundingBox().catch(() => null);
      const free = cb && mb && (cb.y + cb.height < mb.y || cb.y > mb.y + mb.height || cb.x + cb.width < mb.x || cb.x > mb.x + mb.width);
      if (free && cb) await p!.touchscreen.tap(cb.x + cb.width / 2, cb.y + cb.height / 2);
      else await p!.touchscreen.tap(4, 4);
    }
    await expect(openMenu(p!), `ROW-126: ${i % 2 === 0 ? 'Escape' : 'a tap outside'} closes the menu of "${h.word}"`).toHaveCount(0, { timeout: WAIT_MS });
    expect(await readOfferText(p!), `ROW-126: closing the menu of "${h.word}" changes no text`).toBe(text);
    expect(await readHighlights(p!, text), `ROW-126: closing the menu of "${h.word}" leaves every highlight`).toEqual(after.highlights);
    expect((await readCount(p!)).text, `ROW-126: closing the menu of "${h.word}" leaves the count line`).toBe(after.count);
  }
});

test('ROW-126-control-the-highlights-reach-both-edges-of-the-box', async ({ page, browser, browserName }) => {
  asActor('anonymous');
  const p = await phoneAt360(page, browser, browserName);
  test.skip(p === null, "Playwright's Firefox emulates no mobile device; the phone, Chromium and WebKit projects pay ROW-126");
  const rng = freshRandom();
  const text = await checkedAt360(p!, rng, 'ROW-126 control');
  const box = (await el(p!, ROLES.offer).first().boundingBox())!;
  const rects = await p!.locator('[data-element="flag"]').evaluateAll((fs) => fs.map((f) => f.getBoundingClientRect()).map((r) => ({ left: r.left, right: r.right })));
  const left = Math.min(...rects.map((r) => r.left));
  const right = Math.max(...rects.map((r) => r.right));
  expect(left - box.x, `ROW-126 control: a highlight starts within 48 px of the box's left edge (seed ${rng.seed})`).toBeLessThanOrEqual(48);
  expect(right, `ROW-126 control: a highlight ends in the box's right 40 % (seed ${rng.seed})`).toBeGreaterThanOrEqual(box.x + box.width * 0.6);
  expect(text.length).toBeGreaterThan(0);
});
